/// <summary>
///    Controller for the CustInvoicePrintService_RebateExtension batch process.
///    Enables running the print service as a standalone, independently
///    schedulable/triggerable batch job.
/// </summary>
class METRebateFTIPrintController  extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates a new instance of <c>EcoResProductBarcodeAssociationBuilderController</c> class.
/// </summary>
/// <param name = "_args">The controller arguments.</param>
/// <returns>An instance of <c>SysOperationController</c> class.</returns>
public static METRebateFTIPrintController construct(Args _args)
{
    METRebateFTIPrintController controller = new METRebateFTIPrintController(classstr(METRebateFTIPrintService),
                                                                            methodstr(METRebateFTIPrintService, process),
                                                                            SysOperationExecutionMode::ScheduledBatch);
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    controller.parmDialogCaption(strFmt("Ops-Print rebate invoice-LE%1-%2", curExt(), DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())));

    return controller;
}

/// <summary>
///    Static helper: builds and runs the batch job for the given RecIds,
///    entirely in the background (no dialog).
/// </summary>
/// <param name="_custInvoiceJourList">
///    A RecordSortedList of CustInvoiceJour records to print.
/// </param>
public static void main(Args _args)
{
    METRebateFTIPrintController controller;
    METRebateFTIPrintContract contract;
    CustInvoiceTable            custInvoiceTable;
    List custInvoiceTableList;
    List custInvoiceTableRecIdList = new List(Types::Int64);
    ListEnumerator  enumerator;

    if (!_args || !_args.parmObject())
    {
        throw error("No invoice records were provided.");
    }

    custInvoiceTableList = _args.parmObject();

    if (!custInvoiceTableList)
    {
        throw error("Invalid invoice RecId list.");
    }

    if (custInvoiceTableList.elements() == 0)
    {
        return;
    }

    controller = METRebateFTIPrintController::construct(_args);

    contract = controller.getDataContractObject();

    enumerator = custInvoiceTableList.getEnumerator();
    while (enumerator.moveNext())
    {
        custInvoiceTable = enumerator.current();
        if (custInvoiceTable.RecId)
        {
            custInvoiceTableRecIdList.addEnd(custInvoiceTable.RecId);
        }
    }

    if (custInvoiceTableRecIdList.elements() == 0)
    {
        return;
    }

    contract.parmCustInvoiceTableRecIds(custInvoiceTableList);
    controller.startOperation();
}
